23	constexpr int32_t GATHER_MODE_LAST_DIM = 0;
24	constexpr int32_t GATHER_MODE_TRANSPOSE = 1;
25	constexpr int32_t GATHER_MODE_SCALAR = 2;
26	
27	inline int32_t CeilDivI32(int32_t a, int32_t b)
28	{
29	    if (b == 0) { return 0; }
30	    return (a + b - 1) / b;
31	}
32	
33	inline int32_t ChooseBlockM(int32_t m)
34	{
35	    int32_t blockM = 32;
36	    if (m < 32) blockM = 16;
37	    if (m < 16) blockM = 8;
38	    if (m < 8) blockM = 4;
39	    if (m < 4) blockM = 2;
40	    if (m < 2) blockM = 1;
41	    return blockM;
42	}
43	
44	static inline void LaunchGatherElementsV2Kernel(
45	    const at::Tensor &x, const at::Tensor &index, const at::Tensor &row_map,
46	    at::Tensor &y, int32_t xStride, int32_t yStride, int32_t ig32,
47	    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
48	    int32_t subBlockM, int32_t m, int32_t xRows, int32_t mode32)
49	{
50	    at::Tensor tilingCpu = at::empty(
51	        {static_cast<int64_t>(sizeof(GatherElementsV2KernelTiling))},
52	        at::device(at::kCPU).dtype(at::kByte));
53	    auto *tiling = reinterpret_cast<GatherElementsV2KernelTiling *>(tilingCpu.data_ptr());
54	    tiling->M = m;                tiling->XRows = xRows;
55	    tiling->XG = xStride;        tiling->IG = ig32;
56	    tiling->XStride = xStride;   tiling->YStride = yStride;
57	    tiling->blockM = blockM;     tiling->usedCoreNum = usedCoreNum;
58	    tiling->tasksPerCore = tasksPerCore;
59	    tiling->subBlockM = subBlockM;
60	    tiling->useRowMap = (mode32 == GATHER_MODE_LAST_DIM) ? 0 : 1;
61	    tiling->mode = mode32;
62	
63	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
64	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
65	
66	    bool isFp16 = (x.scalar_type() == at::kHalf);
67	    if (mode32 == GATHER_MODE_LAST_DIM) {
68	        if (isFp16) {
69	            EXEC_KERNEL_CMD(gather_elements_v2_last_dim_fp16, blockDim, x, index, row_map, y, tilingNpu);
70	        } else {
71	            EXEC_KERNEL_CMD(gather_elements_v2_last_dim_fp32, blockDim, x, index, row_map, y, tilingNpu);
72	        }
73	    } else if (mode32 == GATHER_MODE_TRANSPOSE) {
74	        if (isFp16) {
75	            EXEC_KERNEL_CMD(gather_elements_v2_transpose_fp16, blockDim, x, index, row_map, y, tilingNpu);
76	        } else {
77	            EXEC_KERNEL_CMD(gather_elements_v2_transpose_fp32, blockDim, x, index, row_map, y, tilingNpu);
78	        }
79	    } else {
80	        if (isFp16) {
81	            EXEC_KERNEL_CMD(gather_elements_v2_scalar_fp16, blockDim, x, index, row_map, y, tilingNpu);
82	        } else {
83	            EXEC_KERNEL_CMD(gather_elements_v2_scalar_fp32, blockDim, x, index, row_map, y, tilingNpu);
84	        }
85	    }
86	}
87	
88	at::Tensor gather_elements_v2(
89	    const at::Tensor &x,
90	    const at::Tensor &index,
91	    const at::Tensor &row_map,
92	    int64_t ig,
93	    int64_t mode)
94	{
95	    TORCH_CHECK(x.device().is_privateuseone(), "x must be on NPU");
96	    TORCH_CHECK(index.device().is_privateuseone(), "index must be on NPU");
97	    TORCH_CHECK(row_map.device().is_privateuseone(), "row_map must be on NPU");
98	    TORCH_CHECK(x.dim() == 2, "x must be [XRows, XStride]");
99	    TORCH_CHECK(index.dim() == 2, "index must be [M, YStride]");
100	    TORCH_CHECK(row_map.dim() == 1, "row_map must be [M]");
101	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
102	    TORCH_CHECK(index.is_contiguous(), "index must be contiguous");
103	    TORCH_CHECK(row_map.is_contiguous(), "row_map must be contiguous");
104	    TORCH_CHECK(index.scalar_type() == at::kInt, "index must be int32");
105	    TORCH_CHECK(row_map.scalar_type() == at::kInt, "row_map must be int32");
106	    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kFloat, "x must be float16 or float32");
107	
108	    const int32_t mode32 = static_cast<int32_t>(mode);
109	    const int32_t m = static_cast<int32_t>(index.size(0));
110	    TORCH_CHECK(index.size(0) == row_map.size(0), "index and row_map row count must match");
111	    const int32_t xRows = static_cast<int32_t>(x.size(0));
112	    const int32_t xStride = static_cast<int32_t>(x.size(1));
113	    const int32_t yStride = static_cast<int32_t>(index.size(1));
114	    const int32_t ig32 = static_cast<int32_t>(ig);
115	
116	    TORCH_CHECK(ig32 >= 0, "ig must be non-negative");
117	    TORCH_CHECK(ig32 <= yStride, "ig must not exceed index width");
118	
119	    const int32_t blockM = ChooseBlockM(std::max(m, 1));
120	    const int32_t mNum = CeilDivI32(std::max(m, 1), blockM);
121	    const int32_t usedCoreNum = std::min(DEFAULT_NUM_PHYSICAL_CORES, std::max(mNum, 1));
122	    const int32_t tasksPerCore = CeilDivI32(mNum, usedCoreNum);
123	    const int32_t subBlockM = std::max(blockM / DEFAULT_VEC_NUM, 1);
124	
125	    at::Tensor y = at::zeros({m, yStride}, x.options());
126	    LaunchGatherElementsV2Kernel(x, index, row_map, y, xStride, yStride, ig32, blockM,
127	                                  usedCoreNum, tasksPerCore, subBlockM, m, xRows, mode32);
128	
129	    return y;
130	}
