28	        GM_ADDR rowMap,
29	        GM_ADDR y,
30	        GM_ADDR tilingGM,
31	        AscendC::TPipe *pipe)
32	    {
33	        CopyTiling(&tiling_, tilingGM);
34	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ DataType *>(x), tiling_.XRows * tiling_.XStride);
35	        indexGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(index), tiling_.M * tiling_.YStride);
36	        if (tiling_.useRowMap != 0) {
37	            rowMapGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(rowMap), tiling_.M);
38	        }
39	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ DataType *>(y), tiling_.M * tiling_.YStride);
40	
41	        if ASCEND_IS_AIV {
42	            pipe_ = pipe;
43	            subBlockRows_ = tiling_.subBlockM;
44	            pipe_->InitBuffer(xInQueue_, 1, AlignedXRowBytes());
45	            pipe_->InitBuffer(indexInQueue_, 1, AlignedIndexRowBytes());
46	            pipe_->InitBuffer(yOutQueue_, 1, AlignedYRowBytes());
47	            if (tiling_.useRowMap != 0) {
48	                pipe_->InitBuffer(rowMapInQueue_, 1, AlignBytes(sizeof(int32_t)));
49	            }
50	        }
51	    }
52	
53	protected:
54	    __aicore__ inline void Process()
55	    {
56	        if ASCEND_IS_AIV {
57	            const GatherElementsV2KernelTiling &tiling = this->Tiling();
58	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
59	            const int subBlockIdx = AscendC::GetSubBlockIdx();
60	
61	            for (int localIdx = 0; localIdx < tiling.tasksPerCore; ++localIdx) {
62	                const int bx = coreIdx * tiling.tasksPerCore + localIdx;
63	                if (bx >= this->BlockCount()) {
64	                    continue;
65	                }
66	
67	                const int rowBase = bx * tiling.blockM + subBlockIdx * tiling.subBlockM;
68	                for (int row = 0; row < this->SubBlockRows(); ++row) {
69	                    const int rowIdx = rowBase + row;
70	                    if (rowIdx < tiling.M) {
71	                        const int32_t xRowIdx = this->ResolveXRowFromMap(rowIdx);
72	                        this->ProcessGatherRow(rowIdx, xRowIdx);
73	                    }
74	                }
75	            }
76	        }
77	    }
78	
79	    __aicore__ inline const GatherElementsV2KernelTiling &Tiling() const
80	    {
81	        return tiling_;
82	    }
83	
84	    __aicore__ inline int32_t SubBlockRows() const
85	    {
86	        return subBlockRows_;
87	    }
88	
89	    __aicore__ inline int32_t BlockCount() const
90	    {
91	        return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM;
92	    }
93	
94	    __aicore__ inline uint32_t XRowBytes() const
95	    {
96	        return static_cast<uint32_t>(tiling_.XStride * sizeof(DataType));
97	    }
98	
99	    __aicore__ inline uint32_t IndexRowBytes() const
100	    {
101	        return static_cast<uint32_t>(tiling_.YStride * sizeof(int32_t));
102	    }
103	
104	    __aicore__ inline uint32_t YRowBytes() const
105	    {
106	        return static_cast<uint32_t>(tiling_.YStride * sizeof(DataType));
107	    }
108	
109	    __aicore__ inline uint32_t AlignBytes(uint32_t bytes) const
110	    {
111	        return ((bytes + 31U) / 32U) * 32U;
112	    }
113	
114	    __aicore__ inline uint32_t AlignedXRowBytes() const
115	    {
116	        return AlignBytes(XRowBytes());
117	    }
118	
119	    __aicore__ inline uint32_t AlignedIndexRowBytes() const
120	    {
121	        return AlignBytes(IndexRowBytes());
122	    }
123	
124	    __aicore__ inline uint32_t AlignedYRowBytes() const
125	    {
126	        return AlignBytes(YRowBytes());
127	    }
128	
129	    __aicore__ inline void CopyXRowToUb(AscendC::LocalTensor<DataType> &dst, AscendC::GlobalTensor<DataType> src)
130	    {
131	        const uint32_t padElems = (AlignedXRowBytes() - XRowBytes()) / sizeof(DataType);
132	        AscendC::DataCopyExtParams copyParams{1, XRowBytes(), 0, 0, 0};
133	        AscendC::DataCopyPadExtParams<DataType> padParams{
134	            true, 0, static_cast<uint8_t>(padElems), static_cast<DataType>(0)};
135	        AscendC::DataCopyPad(dst, src, copyParams, padParams);
136	    }
137	
138	    __aicore__ inline void CopyIndexRowToUb(AscendC::LocalTensor<int32_t> &dst, AscendC::GlobalTensor<int32_t> src)
139	    {
140	        const uint32_t padElems = (AlignedIndexRowBytes() - IndexRowBytes()) / sizeof(int32_t);
141	        AscendC::DataCopyExtParams copyParams{1, IndexRowBytes(), 0, 0, 0};
142	        AscendC::DataCopyPadExtParams<int32_t> padParams{true, 0, static_cast<uint8_t>(padElems), 0};
143	        AscendC::DataCopyPad(dst, src, copyParams, padParams);
144	    }
145	
146	    __aicore__ inline void CopyYRowToGm(AscendC::GlobalTensor<DataType> dst, AscendC::LocalTensor<DataType> &src)
147	    {
148	        AscendC::DataCopyExtParams copyParams{1, YRowBytes(), 0, 0, 0};
149	        AscendC::DataCopyPad(dst, src, copyParams);
150	    }
151	
152	    __aicore__ inline int32_t ResolveXRowFromMap(int rowIdx)
153	    {
154	        if (tiling_.useRowMap == 0) {
155	            return rowIdx;
156	        }
157	
158	        rowMapInQueue_.AllocTensor<int32_t>(rowMapLocal_);
159	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
160	        AscendC::DataCopyPadExtParams<int32_t> padParams{true, 0, 0, 0};
161	        AscendC::DataCopyPad(rowMapLocal_, rowMapGM_[rowIdx], copyParams, padParams);
162	        rowMapInQueue_.EnQue(rowMapLocal_);
163	        rowMapInQueue_.DeQue<int32_t>(rowMapLocal_);
164	        const int32_t mappedRow = rowMapLocal_.GetValue(0);
165	        rowMapInQueue_.FreeTensor(rowMapLocal_);
166	        return mappedRow;
167	    }
168	
169	    __aicore__ inline void ProcessGatherRow(int rowIdx, int32_t xRowIdx)
170	    {
171	        xInQueue_.AllocTensor<DataType>(xLocal_);
172	        indexInQueue_.AllocTensor<int32_t>(indexLocal_);
173	        yOutQueue_.AllocTensor<DataType>(yLocal_);
174	
175	        CopyXRowToUb(xLocal_, xGM_[xRowIdx * tiling_.XStride]);
176	        CopyIndexRowToUb(indexLocal_, indexGM_[rowIdx * tiling_.YStride]);
177	        xInQueue_.EnQue(xLocal_);
178	        indexInQueue_.EnQue(indexLocal_);
179	
180	        xInQueue_.DeQue<DataType>(xLocal_);
181	        indexInQueue_.DeQue<int32_t>(indexLocal_);
182	
183	        AscendC::Duplicate(yLocal_, static_cast<DataType>(0), tiling_.YStride);
184	        AscendC::PipeBarrier<PIPE_ALL>();
185	        for (int col = 0; col < tiling_.IG; ++col) {
186	            const int32_t gatherIdx = indexLocal_.GetValue(col);
187	            const DataType value = xLocal_.GetValue(gatherIdx);
188	            yLocal_.SetValue(col, value);
189	        }
190	        AscendC::PipeBarrier<PIPE_ALL>();
191	
192	        xInQueue_.FreeTensor(xLocal_);
193	        indexInQueue_.FreeTensor(indexLocal_);
194	        yOutQueue_.EnQue(yLocal_);
195	
196	        yOutQueue_.DeQue<DataType>(yLocal_);
197	        CopyYRowToGm(yGM_[rowIdx * tiling_.YStride], yLocal_);
198	        yOutQueue_.FreeTensor(yLocal_);
199	    }
200	
201	private:
202	    GatherElementsV2KernelTiling tiling_{};
203	    AscendC::TPipe *pipe_{nullptr};
204	    int subBlockRows_{0};
205	
206	    AscendC::GlobalTensor<DataType> xGM_;
207	    AscendC::GlobalTensor<int32_t> indexGM_;
208	    AscendC::GlobalTensor<int32_t> rowMapGM_;
209	    AscendC::GlobalTensor<DataType> yGM_;
210	
211	    AscendC::TQue<AscendC::TPosition::VECIN, 0> xInQueue_;
212	    AscendC::TQue<AscendC::TPosition::VECIN, 0> indexInQueue_;
213	    AscendC::TQue<AscendC::TPosition::VECIN, 0> rowMapInQueue_;
214	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> yOutQueue_;
215	
216	    AscendC::LocalTensor<DataType> xLocal_;
217	    AscendC::LocalTensor<int32_t> indexLocal_;
218	    AscendC::LocalTensor<int32_t> rowMapLocal_;
219	    AscendC::LocalTensor<DataType> yLocal_;
220	};
