13	
14	namespace ascend_kernel {
15	
16	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
17	
18	at::Tensor gelu(const at::Tensor &self, int64_t approximate)
19	{
20	    // ---- 输入校验 ----
21	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat ||
22	                self.scalar_type() == at::kBFloat16,
23	                "gelu: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
24	
25	    at::Tensor output = at::empty_like(self);
26	
27	    int64_t totalLength = self.numel();
28	    if (totalLength == 0) {
29	        return output;
30	    }
31	
32	    int64_t dtypeSize = self.element_size();
33	
34	    // ---- 获取硬件参数 ----
35	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
36	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
37	    uint64_t ubSize;
38	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
39	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
40	
41	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
42	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
43	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
44	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
45	
46	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
47	    int64_t formerNum = usedCoreNum - 1;
48	    int64_t formerLength = totalLengthCoreAlign;
49	    int64_t tailLength = totalLength - formerNum * formerLength;
50	
51	    // ---- UB 级 tiling (核内切分) ----
52	    // bufferCoefficient from UB allocation table:
53	    // float32: 24 (inQueueX * 2 + outQueueY * 2 + tmpBuf1 + tmpBuf2 + tmpBuf3 = 8+8+4+4+4 = 28)
54	    // Actually: inQueueX(2*4) + outQueueY(2*4) + 3*tmpBuf(3*4) = 8+8+12 = 28 for float32
55	    // For float16: inQueueX(2*2) + outQueueY(2*2) + 3*tmpBuf(3*4) = 4+4+12 = 20
56	    // Let's use conservative values
57	    int64_t bufferCoefficient;
58	    if (dtypeSize == 4) {
59	        bufferCoefficient = 28;  // float32
60	    } else {
61	        bufferCoefficient = 20;  // float16/bfloat16
62	    }
63	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
64	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
65	    if (dtypeSize == 0) { dtypeSize = 1; }
66	    int64_t alignElements = 32 / dtypeSize;
67	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
68	
69	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
70	
71	    // approximate is already int64_t, pass as left value
72	    EXEC_KERNEL_CMD(gelu, blockDim,
73	                    self, output,
74	                    formerNum, formerLength, tailLength, tileLength, dtypeSize, approximate);
75	
76	    return output;
77	}
