11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	// GELU constants for tanh approximation
16	constexpr float GELU_SQRT_2_OVER_PI = 0.7978845608f;
17	constexpr float GELU_COEFF = 0.044715f;
18	constexpr float GELU_ONE_OVER_SQRT2 = 0.7071067812f;  // 1/sqrt(2)
19	
20	template <typename T>
21	class KernelGelu {
22	public:
23	    __aicore__ inline KernelGelu() {}
24	
25	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
26	                                int64_t formerNum, int64_t formerLength,
27	                                int64_t tailLength, int64_t tileLength,
28	                                int64_t approximate)
29	    {
30	        int64_t blockIdx = AscendC::GetBlockIdx();
31	
32	        if (blockIdx < formerNum) {
33	            this->blockLength = formerLength;
34	            int64_t offset = formerLength * blockIdx;
35	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
36	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
37	        } else {
38	            this->blockLength = tailLength;
39	            int64_t tailIdx = blockIdx - formerNum;
40	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
41	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
42	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
43	        }
44	
45	        this->tileLength = tileLength;
46	        this->approximate = approximate;
47	
48	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
49	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
50	
51	        // For FP16/BF16, need FP32 temp buffers for cast-up compute
52	        if constexpr (sizeof(T) == sizeof(float) / 2) {
53	            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
54	            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
55	            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
56	        } else {
57	            // FP32 path: need temp buffers for intermediate results
58	            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
59	            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
60	            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
61	        }
62	    }
63	
64	    __aicore__ inline void Process()
65	    {
66	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
67	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
68	
69	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
70	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
71	
72	        for (int64_t i = 0; i < tileNum - 1; ++i) {
73	            CopyIn(i, this->tileLength);
74	            Compute(i, this->tileLength);
75	            CopyOut(i, this->tileLength);
76	        }
77	        if (tileNum > 0) {
78	            CopyIn(tileNum - 1, alignedTailLen);
79	            Compute(tileNum - 1, alignedTailLen);
80	            CopyOut(tileNum - 1, alignedTailLen);
81	        }
82	    }
83	
84	private:
85	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
86	    {
87	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
88	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength],
89	                             {1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0});
90	        inQueueX.EnQue(xLocal);
91	    }
92	
93	    __aicore__ inline void ComputeNoneFp32(AscendC::LocalTensor<float> xLocal, AscendC::LocalTensor<float> yLocal,
94	                                            int64_t curTileLength)
95	    {
96	        // gelu(x) = x * 0.5 * (1 + erf(x / sqrt(2)))
97	        // Step 1: tmp1 = x / sqrt(2)
98	        AscendC::LocalTensor<float> tmp1 = tmpBuf1.Get<float>();
99	        AscendC::LocalTensor<float> tmp2 = tmpBuf2.Get<float>();
100	        AscendC::LocalTensor<float> tmp3 = tmpBuf3.Get<float>();
101	
102	        AscendC::Muls(tmp1, xLocal, GELU_ONE_OVER_SQRT2, curTileLength);
103	        // Step 2: tmp2 = erf(tmp1)
104	        AscendC::Erf(tmp2, tmp1, curTileLength);
105	        // Step 3: tmp1 = 1 + erf(...)
106	        AscendC::Adds(tmp1, tmp2, 1.0f, curTileLength);
107	        // Step 4: tmp2 = 0.5 * (1 + erf(...))
108	        AscendC::Muls(tmp2, tmp1, 0.5f, curTileLength);
109	        // Step 5: y = x * 0.5 * (1 + erf(...))
110	        AscendC::Mul(yLocal, xLocal, tmp2, curTileLength);
111	    }
112	
113	    __aicore__ inline void ComputeTanhFp32(AscendC::LocalTensor<float> xLocal, AscendC::LocalTensor<float> yLocal,
114	                                            int64_t curTileLength)
115	    {
116	        // gelu(x) = 0.5 * x * (1 + tanh(sqrt(2/π) * (x + 0.044715 * x^3)))
117	        AscendC::LocalTensor<float> tmp1 = tmpBuf1.Get<float>();
118	        AscendC::LocalTensor<float> tmp2 = tmpBuf2.Get<float>();
119	        AscendC::LocalTensor<float> tmp3 = tmpBuf3.Get<float>();
120	
121	        // Step 1: tmp1 = x^2
122	        AscendC::Mul(tmp1, xLocal, xLocal, curTileLength);
123	        // Step 2: tmp2 = x^3 = x^2 * x
124	        AscendC::Mul(tmp2, tmp1, xLocal, curTileLength);
125	        // Step 3: tmp1 = 0.044715 * x^3
126	        AscendC::Muls(tmp1, tmp2, GELU_COEFF, curTileLength);
127	        // Step 4: tmp2 = x + 0.044715 * x^3
128	        AscendC::Add(tmp2, xLocal, tmp1, curTileLength);
129	        // Step 5: tmp1 = sqrt(2/π) * (x + 0.044715 * x^3)
130	        AscendC::Muls(tmp1, tmp2, GELU_SQRT_2_OVER_PI, curTileLength);
131	        // Step 6: tmp2 = tanh(...)
132	        AscendC::Tanh(tmp2, tmp1, curTileLength);
133	        // Step 7: tmp1 = 1 + tanh(...)
134	        AscendC::Adds(tmp1, tmp2, 1.0f, curTileLength);
135	        // Step 8: tmp2 = 0.5 * x
136	        AscendC::Muls(tmp2, xLocal, 0.5f, curTileLength);
137	        // Step 9: y = 0.5 * x * (1 + tanh(...))
138	        AscendC::Mul(yLocal, tmp2, tmp1, curTileLength);
139	    }
140	
141	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
142	    {
143	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
144	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
145	
146	        if constexpr (sizeof(T) == sizeof(float)) {
147	            // FP32 path: direct compute
148	            AscendC::LocalTensor<float> xFp32 = xLocal.ReinterpretCast<float>();
149	            AscendC::LocalTensor<float> yFp32 = yLocal.ReinterpretCast<float>();
150	            if (this->approximate == 0) {
151	                ComputeNoneFp32(xFp32, yFp32, curTileLength);
152	            } else {
153	                ComputeTanhFp32(xFp32, yFp32, curTileLength);
154	            }
155	        } else {
156	            // FP16/BF16 path: cast up to FP32, compute, cast down
157	            AscendC::LocalTensor<float> xFp32 = tmpBuf1.Get<float>();
158	            AscendC::LocalTensor<float> yFp32 = tmpBuf2.Get<float>();
159	            AscendC::LocalTensor<float> tmpSwap = tmpBuf3.Get<float>();
160	
161	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
162	
163	            if (this->approximate == 0) {
164	                // gelu(x) = x * 0.5 * (1 + erf(x / sqrt(2)))
165	                // Step 1: tmpSwap = x / sqrt(2)
166	                AscendC::Muls(tmpSwap, xFp32, GELU_ONE_OVER_SQRT2, curTileLength);
167	                // Step 2: yFp32 = erf(tmpSwap)
168	                AscendC::Erf(yFp32, tmpSwap, curTileLength);
169	                // Step 3: tmpSwap = 1 + erf(...)
170	                AscendC::Adds(tmpSwap, yFp32, 1.0f, curTileLength);
