10	
11	
12	
13	// ============================================================
14	// 索引类算子 op_kernel 参考代码（逐元素索引模式）
15	// 适用: gather, scatter, scatter_add 等逐元素索引算子
16	// 示例: 以 torch.gather 为例，index 与 output 同形，每行有独立索引
17	// 使用: 本文件演示了三种执行路径(GatherPath/UBPath/ElementPath)、
18	//       多行批量处理、逐行索引加载、Muls索引转换、Gather指令调用等
19	// ============================================================
20	
21	#include "kernel_operator.h"
22	
23	using namespace AscendC;
24	
25	constexpr int64_t UB_CAPACITY = 192 * 1024;
26	constexpr int64_t MAX_GATHER_SRC_BYTES = 32 * 1024;
27	constexpr int64_t MAX_CORES = 40;
28	
29	template<typename T>
30	class <OpName>Kernel {
31	public:
32	    __aicore__ inline <OpName>Kernel() {}
33	
34	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
35	                                 int64_t inputRows, int64_t srcDimSize,
36	                                 int64_t indexSize, int64_t totalRows,
37	                                 int64_t rowOffset);
38	    __aicore__ inline void Process();
39	
40	private:
41	    __aicore__ inline void ProcessGatherPath(int64_t startRow, int64_t numRows);
42	    __aicore__ inline void ProcessUBPath(int64_t row);
43	    __aicore__ inline void ProcessElementPath(int64_t row);
44	
45	    __aicore__ inline void LoadIndexForRow(int64_t row, LocalTensor<int32_t> &indexLocal)
46	    {
47	        DataCopyExtParams params;
48	        params.blockCount = 1;
49	        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
50	        params.srcStride = 0;
51	        params.dstStride = 0;
52	        DataCopyPadExtParams<int32_t> padParams;
53	        padParams.isPad = false;
54	        DataCopyPad(indexLocal, indexGm[row * indexSize_], params, padParams);
55	        PipeBarrier<PIPE_ALL>();
56	    }
57	
58	    __aicore__ inline void WriteOutputForRow(int64_t row, LocalTensor<T> &outputLocal)
59	    {
60	        DataCopyExtParams params;
61	        params.blockCount = 1;
62	        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
63	        params.srcStride = 0;
64	        params.dstStride = 0;
65	        DataCopyPad(outputGm[row * indexSize_], outputLocal, params);
66	        PipeBarrier<PIPE_ALL>();
67	    }
68	
69	private:
70	    TPipe pipe;
71	
72	    // GatherPath: 多行批量缓冲
73	    TBuf<TPosition::VECIN> inputBuf;
74	    TBuf<TPosition::VECIN> indexBuf;    // 逐行索引，每行独立
75	    TBuf<TPosition::VECOUT> outputBuf;
76	
77	    // UBPath: 单行缓冲
78	    TBuf<TPosition::VECIN> ubInputBuf;
79	    TBuf<TPosition::VECIN> ubIndexBuf;
80	    TBuf<TPosition::VECOUT> ubOutputBuf;
81	
82	    // ElementPath: 仅 index + output
83	    TBuf<TPosition::VECIN> indexBufElem;
84	    TBuf<TPosition::VECOUT> outputBufElem;
85	
86	    GlobalTensor<T> inputGm;
87	    GlobalTensor<int32_t> indexGm;
88	    GlobalTensor<T> outputGm;
89	
90	    int64_t inputRows_ = 0;
91	    int64_t srcDimSize_ = 0;
92	    int64_t indexSize_ = 0;
93	    int64_t totalRows_ = 0;
94	    int64_t rowOffset_ = 0;
95	    int64_t inputRowBytes_ = 0;
96	    int64_t indexRowBytes_ = 0;
97	    int64_t outputRowBytes_ = 0;
98	    int64_t maxRowsPerBatch_ = 1;
99	    int8_t path_ = 0;
100	};
101	
102	// =========================== Init: 路径判断与 UB 分配 start ============================
103	
104	template<typename T>
105	__aicore__ inline void <OpName>Kernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
106	                                                int64_t inputRows, int64_t srcDimSize,
107	                                                int64_t indexSize, int64_t totalRows,
108	                                                int64_t rowOffset) {
109	    inputRows_ = inputRows;
110	    srcDimSize_ = srcDimSize;
111	    indexSize_ = indexSize;
112	    totalRows_ = totalRows;
113	    rowOffset_ = rowOffset;
114	
115	    inputGm.SetGlobalBuffer((__gm__ T*)input, inputRows * srcDimSize);
116	    indexGm.SetGlobalBuffer((__gm__ int32_t*)index);
117	    outputGm.SetGlobalBuffer((__gm__ T*)output);
118	
119	    // 32 字节对齐的行字节数
120	    inputRowBytes_  = (srcDimSize * sizeof(T) + 31) / 32 * 32;
121	    indexRowBytes_  = (indexSize * sizeof(int32_t) + 31) / 32 * 32;
122	    outputRowBytes_ = (indexSize * sizeof(T) + 31) / 32 * 32;
123	
124	    // gather/scatter: 索引每行不同，indexBuf 按 maxRowsPerBatch 分配
125	    int64_t perRowUB = inputRowBytes_ + indexRowBytes_ + outputRowBytes_;
126	
127	    if (perRowUB <= UB_CAPACITY && srcDimSize * sizeof(T) <= MAX_GATHER_SRC_BYTES
128	        && srcDimSize * sizeof(T) >= 32) {
129	        // Path 0: GatherPath — 硬件 Gather 指令
130	        path_ = 0;
131	        maxRowsPerBatch_ = UB_CAPACITY / perRowUB;
132	        if (maxRowsPerBatch_ < 1) maxRowsPerBatch_ = 1;
133	        pipe.InitBuffer(inputBuf,  maxRowsPerBatch_ * inputRowBytes_);
134	        pipe.InitBuffer(indexBuf,  maxRowsPerBatch_ * indexRowBytes_);
135	        pipe.InitBuffer(outputBuf, maxRowsPerBatch_ * outputRowBytes_);
136	    } else if (perRowUB <= UB_CAPACITY) {
137	        // Path 1: UBPath — 标量 UB 访问
138	        path_ = 1;
139	        pipe.InitBuffer(ubInputBuf,  inputRowBytes_);
140	        pipe.InitBuffer(ubIndexBuf,  indexRowBytes_);
141	        pipe.InitBuffer(ubOutputBuf, outputRowBytes_);
142	    } else {
143	        // Path 2: ElementPath — 逐元素 GM 直接访问
144	        path_ = 2;
145	        pipe.InitBuffer(indexBufElem,  indexRowBytes_);
146	        pipe.InitBuffer(outputBufElem, outputRowBytes_);
147	    }
148	}
149	
150	// =========================== Init end ============================
151	
152	
153	// =========================== GatherPath start ============================
154	// 核心接口: DataCopyPad + Muls + ReinterpretCast + Gather
155	// **关键点**: Gather 的 index 参数必须是字节偏移(uint32_t)，
156	//           需先用 Muls 将元素索引乘以 sizeof(T) 转换。
157	// gather/scatter: 每行有独立索引，需逐行加载 index
158	
159	template<typename T>
160	__aicore__ inline void <OpName>Kernel<T>::ProcessGatherPath(int64_t startRow, int64_t numRows) {
161	    LocalTensor<T> inputLocal = inputBuf.Get<T>();
162	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
163	    LocalTensor<T> outputLocal = outputBuf.Get<T>();
164	
165	    // 1. 逐行加载 input → UB
166	    DataCopyExtParams inputCopyParams;
167	    inputCopyParams.blockCount = 1;
168	    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
169	    inputCopyParams.srcStride = 0;
170	    inputCopyParams.dstStride = 0;
171	    DataCopyPadExtParams<T> inputPadParams;
172	    inputPadParams.isPad = false;
173	    for (int64_t r = 0; r < numRows; r++) {
174	        DataCopyPad(inputLocal[r * (inputRowBytes_ / sizeof(T))],
175	                    inputGm[(startRow + r) * srcDimSize_], inputCopyParams, inputPadParams);
176	    }
177	    PipeBarrier<PIPE_ALL>();
178	
179	    // 2. 逐行加载 index → UB（每行有独立索引）
180	    DataCopyExtParams indexCopyParams;
181	    indexCopyParams.blockCount = 1;
182	    indexCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
183	    indexCopyParams.srcStride = 0;
184	    indexCopyParams.dstStride = 0;
185	    DataCopyPadExtParams<int32_t> indexPadParams;
186	    indexPadParams.isPad = false;
187	    for (int64_t r = 0; r < numRows; r++) {
188	        DataCopyPad(indexLocal[r * (indexRowBytes_ / sizeof(int32_t))],
189	                    indexGm[(startRow + r) * indexSize_], indexCopyParams, indexPadParams);
190	    }
191	    PipeBarrier<PIPE_ALL>();
192	
193	    // 3. Muls: 元素索引 → 字节偏移（关键步骤！）
194	    for (int64_t r = 0; r < numRows; r++) {
195	        int64_t off = r * (indexRowBytes_ / sizeof(int32_t));
196	        Muls(indexLocal[off], indexLocal[off], (int32_t)sizeof(T), indexSize_);
197	    }
198	    PipeBarrier<PIPE_ALL>();
199	
200	    // 4. ReinterpretCast + Gather
201	    LocalTensor<uint32_t> indexUintLocal = indexLocal.ReinterpretCast<uint32_t>();
202	    for (int64_t r = 0; r < numRows; r++) {
203	        int64_t inOff  = r * (inputRowBytes_ / sizeof(T));
204	        int64_t idxOff = r * (indexRowBytes_ / sizeof(uint32_t));
205	        int64_t outOff = r * (outputRowBytes_ / sizeof(T));
206	        Gather(outputLocal[outOff], inputLocal[inOff], indexUintLocal[idxOff],
207	               (uint32_t)0, static_cast<uint32_t>(indexSize_));
208	        PipeBarrier<PIPE_ALL>();
209	    }
210	
211	    // 5. 逐行写回 output UB → GM
212	    DataCopyExtParams outputCopyParams;
213	    outputCopyParams.blockCount = 1;
214	    outputCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
215	    outputCopyParams.srcStride = 0;
216	    outputCopyParams.dstStride = 0;
217	    for (int64_t r = 0; r < numRows; r++) {
218	        DataCopyPad(outputGm[(startRow + r) * indexSize_],
219	                    outputLocal[r * (outputRowBytes_ / sizeof(T))], outputCopyParams);
220	    }
221	    PipeBarrier<PIPE_ALL>();
222	}
223	// =========================== GatherPath end ============================
224	
225	
226	// =========================== UBPath start ============================
227	// 当 input 行放得进 UB 但不满足 Gather 约束时，使用标量 GetValue/SetValue
228	
229	template<typename T>
230	__aicore__ inline void <OpName>Kernel<T>::ProcessUBPath(int64_t row) {
231	    LocalTensor<T> inputLocal = ubInputBuf.Get<T>();
232	    LocalTensor<int32_t> indexLocal = ubIndexBuf.Get<int32_t>();
233	    LocalTensor<T> outputLocal = ubOutputBuf.Get<T>();
234	
235	    // 加载 input 行
236	    DataCopyExtParams inputCopyParams;
237	    inputCopyParams.blockCount = 1;
238	    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
239	    inputCopyParams.srcStride = 0;
240	    inputCopyParams.dstStride = 0;
241	    DataCopyPadExtParams<T> inputPadParams;
242	    inputPadParams.isPad = false;
243	    DataCopyPad(inputLocal, inputGm[row * srcDimSize_], inputCopyParams, inputPadParams);
244	    PipeBarrier<PIPE_ALL>();
245	
246	    // 加载该行的 index（每行独立索引）
247	    LoadIndexForRow(row, indexLocal);
248	
249	    // 标量索引收集
250	    for (int64_t j = 0; j < indexSize_; j++) {
251	        int32_t idx = indexLocal.GetValue(j);
252	        T val = inputLocal.GetValue(idx);
253	        outputLocal.SetValue(j, val);
254	    }
255	    PipeBarrier<PIPE_ALL>();
256	
257	    // 写回 output
258	    WriteOutputForRow(row, outputLocal);
259	}
260	// =========================== UBPath end ============================
261	
262	
263	// =========================== ElementPath start ============================
264	// 当 perRowUB 超出 UB 容量时，仅加载 index，直接从 GM 读取 input
265	
266	template<typename T>
267	__aicore__ inline void <OpName>Kernel<T>::ProcessElementPath(int64_t row) {
268	    LocalTensor<int32_t> indexLocal = indexBufElem.Get<int32_t>();
269	    LocalTensor<T> outputLocal = outputBufElem.Get<T>();
270	
271	    // 加载该行的 index
272	    LoadIndexForRow(row, indexLocal, indexBufElem, static_cast<int32_t>(indexRowBytes_));
273	
274	    // 逐元素从 GM 直接读取
275	    for (int64_t j = 0; j < indexSize_; j++) {
276	        int32_t idx = indexLocal.GetValue(j);
277	        T val = inputGm.GetValue(row * srcDimSize_ + idx);
278	        outputLocal.SetValue(j, val);
279	    }
280	    PipeBarrier<PIPE_ALL>();
281	
282	    // 写回 output
283	    WriteOutputForRow(row, outputLocal);
284	}
285	// =========================== ElementPath end ============================
286	
287	
288	// =========================== Process 主入口 start ============================
289	
290	template<typename T>
291	__aicore__ inline void <OpName>Kernel<T>::Process() {
292	    int64_t blockIdx_ = GetBlockIdx();
293	
294	    if (path_ == 0) {
295	        // GatherPath: 连续块分配 + 多行批量处理
296	        int64_t blockDim = (totalRows_ < MAX_CORES) ? totalRows_ : MAX_CORES;
297	        int64_t base = totalRows_ / blockDim;
298	        int64_t remainder = totalRows_ % blockDim;
299	        int64_t myStart, myRows;
300	        if (blockIdx_ < remainder) {
301	            myStart = rowOffset_ + blockIdx_ * (base + 1);
302	            myRows = base + 1;
303	        } else {
304	            myStart = rowOffset_ + remainder * (base + 1) + (blockIdx_ - remainder) * base;
305	            myRows = base;
306	        }
307	
308	        for (int64_t r = myStart; r < myStart + myRows; r += maxRowsPerBatch_) {
309	            int64_t numRows = myStart + myRows - r;
310	            if (numRows > maxRowsPerBatch_) numRows = maxRowsPerBatch_;
311	            ProcessGatherPath(r, numRows);
312	        }
313	    } else {
314	        // UBPath / ElementPath: 交错行分配
315	        int64_t startRow = rowOffset_ + blockIdx_;
316	        for (int64_t r = startRow; r < rowOffset_ + totalRows_; r += MAX_CORES) {
317	            if (r >= inputRows_) break;
318	            if (path_ == 1) {
319	                ProcessUBPath(r);
320	            } else {
321	                ProcessElementPath(r);
322	            }
323	        }
324	    }
325	}
326	// =========================== Process 主入口 end ============================
327	
328	
329	// =========================== Kernel 入口 start ============================
330	// 搬运类算子不做数值计算，bf16 与 fp16 均为 2 字节，统一走 half 路径搬运
331	
332	extern "C" __global__ __aicore__ void <op_name>(GM_ADDR input, GM_ADDR index, GM_ADDR output,
333	                                                  int64_t inputRows, int64_t srcDimSize,
334	                                                  int64_t indexSize, int64_t dtypeSize,
335	                                                  int64_t totalRows, int64_t rowOffset) {
336	    if (dtypeSize == 4) {
337	        <OpName>Kernel<float> op;
338	        op.Init(input, index, output, inputRows, srcDimSize, indexSize, totalRows, rowOffset);
339	        op.Process();
340	    } else if (dtypeSize == 2) {
341	        // fp16 和 bf16 均为 2 字节，搬运类算子可直接用 half 路径
342	        <OpName>Kernel<half> op;
343	        op.Init(input, index, output, inputRows, srcDimSize, indexSize, totalRows, rowOffset);
344	        op.Process();
345	    }
346	}
347	// =========================== Kernel 入口 end ============================
348	
349	
350	// =========================== DMA同步（可选优化）start ============================
351	// 正确性验证后，可将 PipeBarrier<PIPE_ALL>() 替换为以下轻量同步：
352	
353	// CPU 等待 MTE2 (GM→UB) 搬运完成
354	__aicore__ inline void WaitMte2Done() {
355	    event_t evt = static_cast<event_t>(
356	        GetTPipePtr()->FetchEventID(AscendC::HardEvent::MTE2_S));
357	    AscendC::SetFlag<AscendC::HardEvent::MTE2_S>(evt);
358	    AscendC::WaitFlag<AscendC::HardEvent::MTE2_S>(evt);
359	}
360	
361	// CPU 等待 Vector 计算完成
362	__aicore__ inline void WaitVDone() {
363	    event_t evt = static_cast<event_t>(
364	        GetTPipePtr()->FetchEventID(AscendC::HardEvent::V_S));
365	    AscendC::SetFlag<AscendC::HardEvent::V_S>(evt);
366	    AscendC::WaitFlag<AscendC::HardEvent::V_S>(evt);
367	}
368	
369	// CPU 等待 MTE3 (UB→GM) 搬运完成
370	__aicore__ inline void WaitMte3Done() {
371	    event_t evt = static_cast<event_t>(
372	        GetTPipePtr()->FetchEventID(AscendC::HardEvent::MTE3_S));
373	    AscendC::SetFlag<AscendC::HardEvent::MTE3_S>(evt);
374	    AscendC::WaitFlag<AscendC::HardEvent::MTE3_S>(evt);
375	}
376	// =========================== DMA同步（可选优化）end ============================
