#include "torch_kernel_helper.h"
#include "aclrtlaunch_gather.h"

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;

at::Tensor gather(const at::Tensor &x, int64_t dim, const at::Tensor &index, bool sparse_grad) {
    // ---- 输入校验 ----
    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1,
                "gather: x must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "gather: index must be on NPU device");

    int64_t ndim = x.dim();
    if (dim < 0) dim += ndim;

    TORCH_CHECK(dim >= 0 && dim < ndim,
                "gather: dim out of range, got dim=", dim);
    TORCH_CHECK(index.dim() == ndim,
                "gather: index must have same ndim as x");

    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "gather: only float32, float16 and bfloat16 are supported");

    // ---- 连续化 ----
    at::Tensor xContiguous = x.contiguous();
    at::Tensor indexContiguous = index.contiguous();

    // ---- 维度参数 ----
    int64_t N = xContiguous.size(dim);   // 源维度大小
    int64_t K = indexContiguous.size(dim); // 索引维度大小

    // fp16 和 bf16 均为 2 字节，kernel 统一走 half 路径搬运
    int64_t dtypeSize = xContiguous.element_size();

    // ---- Index 转 int32 ----
    auto indexInt32 = indexContiguous.to(at::kInt);

    // ---- 3D 维度统一化 ----
    // transpose(dim, -1) 将 dim 移到最后一维，再 reshape 为 [batch, rows, N/K]
    int64_t batch = 1;
    for (int64_t i = 0; i < dim; i++) batch *= xContiguous.size(i);
    int64_t rows = xContiguous.numel() / (batch * N);

    auto xFlat = xContiguous.transpose(dim, -1).contiguous()
                           .reshape({batch, rows, N});
    auto indexFlat = indexInt32.transpose(dim, -1).contiguous()
                                .reshape({batch, rows, K});

    auto outputFlat = at::empty({batch, rows, K},
        xContiguous.options().dtype(
            xContiguous.scalar_type() == at::kBFloat16
                ? at::kBFloat16 : xContiguous.scalar_type()));

    // ---- Tiling 计算 ----
    int64_t totalRows = batch * rows;
    int64_t rowOffset = 0;
    uint32_t blockDim = static_cast<uint32_t>(std::min(totalRows, MAX_CORES));
    if (blockDim < 1) blockDim = 1;

    // 所有参数必须是左值
    EXEC_KERNEL_CMD(gather, blockDim, xFlat, indexFlat, outputFlat,
                    totalRows, N, K, dtypeSize, totalRows, rowOffset);

    // ---- 输出 reshape ----
    // [batch, rows, K] → transpose 还原 → index.sizes()
    std::vector<int64_t> transposedOutShape;
    for (int64_t i = 0; i < ndim; i++) {
        if (i == dim) continue;
        transposedOutShape.push_back(indexContiguous.size(i));
    }
    transposedOutShape.push_back(K);

    auto outputContiguous = outputFlat.reshape(transposedOutShape)
                                       .transpose(ndim - 1, dim).contiguous();

    return outputContiguous.reshape(index.sizes());
}

}  // namespace ascend_kernel
