43	{
44	    (void)dim;  // dim is handled by the Python wrapper
45	
46	    // x is expected to be [totalRows, N] 2D tensor
47	    TORCH_CHECK(x.dim() == 2, "x must be [totalRows, N]");
48	    TORCH_CHECK(
49	        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
50	            x.scalar_type() == at::kBFloat16,
51	        "x must be float32, float16, or bfloat16");
52	    TORCH_CHECK(k > 0, "k must be > 0");
53	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
54	
55	    int32_t totalRows = static_cast<int32_t>(x.sizes()[0]);
56	    int32_t N = static_cast<int32_t>(x.sizes()[1]);
57	    int32_t kVal = static_cast<int32_t>(k);
58	
59	    TORCH_CHECK(kVal <= N, "k must be <= N");
60	
61	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
62	    int64_t dtypeFlag = 0;
63	    if (x.scalar_type() == at::kHalf) {
64	        dtypeFlag = 1;
65	    } else if (x.scalar_type() == at::kBFloat16) {
