71	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
72	    int32_t usedCoreNum = static_cast<int32_t>(std::min(coreNum, static_cast<int64_t>(totalRows)));
73	    if (usedCoreNum < 1) { usedCoreNum = 1; }
74	    int32_t tasksPerCore = (totalRows + usedCoreNum - 1) / usedCoreNum;
75	
76	    // Allocate output tensor
77	    auto options = x.options();
78	    at::Tensor y = at::empty({totalRows, kVal}, options);
79	
80	    // All params as left values (required by EXEC_KERNEL_CMD)
81	    int32_t totalRowsLv = totalRows;
82	    int32_t nLv = N;
83	    int32_t kLv = kVal;
84	    int32_t coreNumLv = usedCoreNum;
85	    int32_t tasksLv = tasksPerCore;
86	    int64_t isLargestLv = largest ? 1 : 0;
87	    int64_t dtypeFlagLv = dtypeFlag;
88	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
